mapper.select:
SELECT M.*, CV.ConstrValDesc AS NationName
FROM shopwizard.tCatMaker M
LEFT OUTER JOIN (SELECT * FROM wizardn.tCodConstrVal WHERE ConstrCode = 'cNationCode') CV ON M.NationCode = CV.ConstrVal

    AND M.MakerId = #{pMakerId}

        AND (M.MakerKorName LIKE CONCAT('%',#{pMakerName},'%') OR M.MakerEngName LIKE CONCAT('%',#{pMakerName},'%'))


ORDER BY M.${sidx} ${sord}
LIMIT #{pPageOffset}, #{pPageSize}

SELECT COUNT(*) FROM shopwizard.tCatMaker M LEFT OUTER JOIN (SELECT * FROM wizardn.tCodConstrVal WHERE ConstrCode = 'cNationCode') CV ON M.NationCode = CV.ConstrVal
AND M.MakerId = #{pMakerId}
AND (M.MakerKorName LIKE CONCAT('%',#{pMakerName},'%') OR M.MakerEngName LIKE CONCAT('%',#{pMakerName},'%'))

mapper.insert:
INSERT INTO shopwizard.tCatMaker (
    MakerKorName, MakerEngName, PrsdntName, NationCode, State, Remark, RegistDate, RegistId, RegistName
) VALUES (
    #{makerKorName}, #{makerEngName}, #{prsdntName}, #{nationCode}, #{state}, #{remark}, NOW(), #{registId}, #{registName}
)

mapper.update:
UPDATE shopwizard.tCatMaker SET
    MakerKorName = #{makerKorName}, MakerEngName = #{makerEngName}, PrsdntName = #{prsdntName},
    NationCode = #{nationCode}, State = #{state}, Remark = #{remark},
    ChangeDate = NOW(), ChangeId = #{changeId}, ChangeName = #{changeName}
WHERE MakerId = #{makerId}
